# ── Caché ─────────────────────────────────────────────────────────
_cache: dict = {}


def _load(name: str, size: int, variant: str):
    """Decodifica el PNG pre-renderizado o intenta el tamaño más cercano."""
    entry = _PNG.get(name, {})
    data = entry.get(size) or entry.get(min(entry, key=lambda s: abs(s - size), default=None))
    if not data:
        return None
    b64 = data.get(variant)
    if not b64:
        return None
    try:
        from PIL import Image
        return Image.open(io.BytesIO(base64.b64decode(b64)))
    except Exception:
        return None


def get(name: str, size: int = 18):
    """
    Devuelve un CTkImage del heroicon solicitado, con variante dark/light.
    Retorna None si Pillow no está disponible.
    """
    import customtkinter as ctk
    key = (name, size)
    if key in _cache:
        return _cache[key]
    light_img = _load(name, size, "light")
    dark_img  = _load(name, size, "dark")
    if light_img and dark_img:
        result = ctk.CTkImage(light_image=light_img, dark_image=dark_img, size=(size, size))
    else:
        result = None
    _cache[key] = result
    return result
